def translate(text: str, locale: str) -> str:
    """Portuguese for `text`, or `text` unchanged.

    Unchanged covers three cases that should all behave the same way: an English locale, a
    string deliberately left untranslated (a product name), and copy edited in the
    descriptors since this file was written. The last one is why the source text is the
    key — a stale translation would otherwise ship silently.
    """
    if locale != "pt-BR" or not text:
        return text
    return PT_BR.get(text, text)


def translate_all(items: list[str], locale: str) -> list[str]:
    return [translate(item, locale) for item in items]
